const RELEASE_CONFIG=window.TWENTYONE_RELEASE;
const APP=RELEASE_CONFIG.appUrl;
const REPO='https://github.com/marco201091-glitch/21life';
const RELEASE=REPO+'/releases/latest';
const APK=RELEASE_CONFIG.apkUrl;
const routes=['home','info','download','guida','confronto','supporto'];
const route=routes.includes(location.pathname.split('/').filter(Boolean)[0])?location.pathname.split('/').filter(Boolean)[0]:'home';
let lang=new URLSearchParams(location.search).get('lang')==='it'?'it':'en';
const t=(it,en)=>lang==='it'?it:en;
const url=(r)=> (r==='home'?'/':'/'+r+'/')+(lang==='it'?'?lang=it':'');
const link=(r,label,cls='')=>`<a class="${cls}" href="${url(r)}" ${route===r?'aria-current="page"':''}>${label}</a>`;
const button=(href,label,primary=false)=>href===APK&&!RELEASE_CONFIG.downloadsEnabled?`<span class="btn disabled" aria-disabled="true">${t(`APK ${RELEASE_CONFIG.version} · in arrivo`,`APK ${RELEASE_CONFIG.version} · coming soon`)}</span>`:`<a class="btn ${primary?'primary':''}" href="${href}">${label} <span aria-hidden="true">↗</span></a>`;
const navLabels=()=>[t('Home','Home'),t('Funzioni','Features'),t('Download','Download'),t('Guida','Guide'),t('Confronto','Compare'),t('Supporto','Support')];
const heading=(label,title,desc)=>`<div class="page-hero"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>`;
const features=()=>[
 [t('Contavita','Life counter'),t('Apri una partita e metti il telefono al centro del tavolo. Il contavita è pronto per tutto il gruppo.','Start a game and put your phone in the middle of the table. One life counter for the whole group.')],
 [t('Storico partite','Match history'),t('Chi ha vinto, con quale mazzo, contro chi. Le partite del gruppo restano salvate e tutti possono consultarle.','Who won, which deck they played, who they faced. Your group’s games are saved for everyone to look back on.')],
 [t('Statistiche','Statistics'),t('Come va il nuovo mazzo? Chi vince più spesso? Guarda i risultati dei giocatori e dei mazzi, partita dopo partita.','How is your new deck doing? Who wins most often? Compare players and decks across the games you play.')]
];
function featureIcon(kind){
 const paths={table:'<rect x="5" y="7" width="22" height="18" rx="4"/><path d="M16 11v10M11 16h10M9 4h14M9 28h14"/>',group:'<circle cx="16" cy="10" r="4"/><path d="M8 26v-3a8 8 0 0 1 16 0v3M5 12a3 3 0 0 0 0 6M27 12a3 3 0 0 1 0 6M3 26v-2a5 5 0 0 1 3-4M29 26v-2a5 5 0 0 0-3-4"/>',analytics:'<path d="M5 26h23M8 22v-7M16 22V9M24 22V4M6 10l8-5 7 1 6-4"/>',deck:'<rect x="7" y="7" width="18" height="23" rx="3"/><path d="M12 3h13a4 4 0 0 1 4 4v18M16 12l5 6-5 6-5-6Z"/>',web:'<rect x="3" y="5" width="26" height="18" rx="3"/><path d="M11 28h10M16 23v5M3 11h26"/>',android:'<path d="M7 14v11h18V14a9 9 0 0 0-18 0ZM10 5 7 1M22 5l3-4M3 14v9M29 14v9M11 25v5M21 25v5"/><path d="M12 10h.01M20 10h.01"/>'};
 return `<svg class="feature-icon" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]||paths.deck}</svg>`;
}
function home(){
 const pillars=features();
 return `<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="hero-kicker"><span class="release-pill">V${RELEASE_CONFIG.version}</span><span>COMMANDER TRACKER & ANALYTICS</span></div><h1 id="hero-title">${t('Il tracker per<br><em>Commander.</em><br>Gratis. Open source.','Your <em>Commander</em><br>tracker.<br>Free. Open source.')}</h1><p class="lead">${t('Contavita, storico delle partite e statistiche per il tuo playgroup. Importa i mazzi da Moxfield o Archidekt. Tutte le funzioni sono gratuite, il codice è pubblico con licenza MIT.','A life counter, match history and statistics for your playgroup. Import decks from Moxfield or Archidekt. All features are free, with public source code under the MIT license.')}</p><div class="actions">${button(url('download'),t('Scarica per Android','Download for Android'),true)}${button(APP,t('Apri la web app','Open the web app'))}</div><div class="hero-platforms"><span>${featureIcon('android')}Android</span><span>${featureIcon('web')}Web</span><span>EN / IT</span></div></div><div class="hero-art"><div class="art-ring ring-one" aria-hidden="true"></div><div class="art-ring ring-two" aria-hidden="true"></div><span class="art-coordinate coordinate-top" aria-hidden="true">21 / LIFE</span><img src="/assets/emblem.png" width="1280" height="1280" alt="${t('Emblema 21Life: dado a venti facce con il numero 21','21Life emblem: a twenty-sided die with the number 21')}" fetchpriority="high"><div class="art-caption"><span class="caption-dot" aria-hidden="true"></span>${t('21LIFE · COMMANDER TRACKER','21LIFE · COMMANDER TRACKER')}</div></div><div class="hero-bottom"><span>${t('Contavita · Partite · Statistiche','Life counter · Games · Statistics')}</span><a href="#experience">${t('Esplora','Explore')} <span aria-hidden="true">↓</span></a></div></section>
 <div class="strip"><div><strong>2–6 ${t('giocatori','players')}</strong>${t('Contavita multiplayer','Multiplayer life counter')}</div><div><strong>${t('Un account','One account')}</strong>Android & Web</div><div><strong>Archidekt / Moxfield</strong>${t('Importa i tuoi mazzi','Import your decks')}</div><div><strong>Open source</strong>${t('Codice disponibile · Licenza MIT','Source available · MIT licence')}</div></div>
 <section id="experience" class="experience"><div class="section-top"><div><div class="eyebrow">${t('COSA FA 21LIFE','WHAT 21LIFE DOES')}</div><h2>${t('Al tavolo e tra una partita e l’altra.','At the table. Between games.')}</h2></div><p>${t('Il contavita per giocare. Lo storico e le statistiche per chi vuole tenere il conto anche delle vittorie.','A life counter for playing. Match history and statistics for keeping track of the wins, too.')}</p></div><div class="grid feature-grid">${pillars.map(([title,text],i)=>`<article class="card feature-card"><div class="card-top">${featureIcon(['table','group','analytics'][i])}<span class="number">0${i+1}</span></div><h3>${title}</h3><p>${text}</p>${link('info',t('Scopri le funzioni','See the features'),'feature-link')}<span class="card-edge" aria-hidden="true"></span></article>`).join('')}</div></section>
 <section class="section-panel preview-editorial"><div class="two"><div><div class="eyebrow">COMMANDER · EDH · GAME TRACKER</div><h2>${t('Come sta andando<br>il tuo <em>mazzo?</em>','How is your<br><em>deck</em> doing?')}</h2><p>${t('Importa i mazzi che giochi e usali nelle partite del gruppo. I risultati si raccolgono in un solo posto: puoi confrontarli quando cambi lista o provi un altro comandante.', 'Import your decks and play them with your group. Results stay in one place, ready to compare when you change your list or try another commander.')}</p></div><div class="preview-guides">${link('guida',t('Da dove cominciare →','Getting started →'),'text-link')}${link('info',t('Mazzi e statistiche →','Decks and statistics →'),'text-link')}</div></div></section>${draftOpenSource()}${draftFaq()}<section class="closing-section"><div class="cta"><div><div class="eyebrow">${t('ANDROID E WEB','ANDROID AND WEB')}</div><h2>${t('Provalo alla prossima partita.','Try it at your next game.')}</h2><p>${t('Installa l’app Android oppure apri 21Life dal browser.','Install the Android app or open 21Life in your browser.')}</p></div><div class="cta-actions">${button(url('download'),t('Vai al download','Go to downloads'),true)}<a href="${url('supporto')}" class="quiet-link">${t('Domande frequenti','Frequently asked questions')}</a></div></div></section>`;
}

function baseInfo(){return heading(t('INFO / IL PROGETTO','ABOUT / THE PROJECT'),t('Contavita, partite<br>e statistiche.','Life counter, games<br>and statistics.'),t('21Life è un tracker per partite Commander: unisce contavita, storico condiviso e analisi di giocatori e mazzi.','21Life is a Commander game tracker that brings together a life counter, shared history and player and deck analytics.'))+`<section class="content-section"><div class="grid">${features().map(([title,text],i)=>`<article class="card"><span class="number">0${i+1}</span><h3>${title}</h3><p>${text}</p></article>`).join('')}</div></section><section class="section-panel"><div class="two"><div><div class="eyebrow">${t('MAZZI & IMPORTAZIONE','DECKS & IMPORTS')}</div><h2>${t('I mazzi che giochi.<br>I risultati che fanno.','The decks you play.<br>The results they get.')}</h2><p>${t('Importa i tuoi mazzi da Archidekt o Moxfield e associali alle partite. Le statistiche ti aiutano a capire quali funzionano meglio nel tuo gruppo.','Import your decks from Archidekt or Moxfield and use them in your games. Statistics help you see which ones perform best in your group.')}</p></div><div><ul class="list"><li>${t('Classifiche per giocatori, mazzi e comandanti','Rankings for players, decks and commanders')}</li><li>${t('Stagioni e premi del playgroup','Playgroup seasons and awards')}</li><li>${t('Statistiche personali e serie di vittorie','Personal statistics and winning streaks')}</li><li>${t('Risultati pubblici opzionali per il gruppo','Optional public group results')}</li><li>${t('Storico condiviso del gruppo','Shared group match history')}</li></ul></div></div></section><section><div class="two"><div><div class="eyebrow">OPEN SOURCE</div><h2>${t('Un progetto aperto.','An open project.')}</h2><p>${t('Il codice di 21Life è disponibile su GitHub con licenza MIT. Puoi consultarlo, segnalare problemi e proporre miglioramenti.','21Life’s code is available on GitHub under the MIT licence. Explore it, report issues and suggest improvements.')}</p>${button(REPO,t('Esplora il codice','Explore the source'))}</div><div><h3>${t('Lo stesso account, su Android e web','One account for Android and web')}</h3><p>${t('Accedi da telefono o browser per ritrovare il tuo gruppo, i mazzi e le partite. Per sincronizzare i dati e importare i mazzi serve una connessione internet.','Sign in on your phone or in a browser to access your group, decks and games. Syncing data and importing decks require an internet connection.')}</p><div class="legal-links"><a href="${APP}/legal/privacy">${t('Privacy','Privacy')}</a><a href="${url('supporto')}#account">${t('Eliminazione account','Account deletion')}</a></div></div></div></section>`}
function download(){return draftDownload();}
function baseGuide(){const steps=[
[t('Apri 21Life e crea il tuo account','Open 21Life and create your account'),t('Usa la web app o installa Android. Accedi con email e password oppure con Google nella versione standard.','Use the web app or install Android. Sign in with email and password, or with Google in the standard edition.')],
[t('Crea o raggiungi il tuo playgroup','Create or join your playgroup'),t('Riunisci il tuo gruppo in uno spazio privato. Invita gli altri membri; puoi aggiungere ospiti alle partite senza richiedere loro un account.','Bring your group together in a private space. Invite members and add guests to games without requiring an account.')],
[t('Aggiungi i tuoi mazzi','Add your decks'),t('Aggiungi i mazzi che giochi oppure importali da Archidekt o Moxfield. Controlla comandanti e identità di colore prima della partita.','Add the decks you play or import them from Archidekt or Moxfield. Check commanders and colour identity before the game.')],
[t('Prepara il tavolo','Set up the table'),t('Nel wizard della partita seleziona partecipanti, mazzi, vita iniziale e disposizione. Il tavolo supporta da 2 a 6 giocatori.','In the game wizard, select players, decks, starting life and layout. The table supports 2–6 players.')],
[t('Gioca e registra il risultato','Play and record the result'),t('Gestisci vita, danni ed eliminazioni. Alla fine registra vincitore e condizione di vittoria, oppure il pareggio. Il risultato alimenta storico e statistiche.','Manage life, damage and eliminations. Record the winner and win condition, or a draw. The result feeds your history and statistics.')],
[t('Consulta le statistiche','Check your statistics'),t('Esplora le classifiche del gruppo, le prestazioni dei mazzi e i premi. Usa i filtri per confrontare partite e bracket pertinenti.','Explore group rankings, deck performance and awards. Use filters to compare relevant games and brackets.')]
];return heading(t('GUIDA / PRIMI PASSI','GUIDE / FIRST STEPS'),t('Come iniziare.','Getting started.'),t('Sei passaggi per iniziare con il tuo gruppo.','Six steps to get started with your group.'))+`<section class="content-section"><div class="two"><div><ol class="steps">${steps.map(([a,b])=>`<li><h3>${a}</h3><p>${b}</p></li>`).join('')}</ol></div><div><div class="card"><div class="eyebrow">${t('PRIMA DI INIZIARE','BEFORE YOU START')}</div><h3>${t('Serve una connessione internet','An internet connection is required')}</h3><p>${t('Account, sincronizzazione e importazione dei mazzi richiedono internet. Se una partita si interrompe, riapri l’app per riprenderla.','Accounts, syncing and deck imports require internet. If a game is interrupted, reopen the app to resume it.')}</p><div class="actions">${button(APP,t('Inizia nella web app','Start in the web app'),true)}</div></div><div class="card"><h3>${t('Qualcosa non torna?','Something wrong?')}</h3><p>${t('Consulta le domande frequenti o scrivici indicando piattaforma e versione dell’app.','Read the FAQ or contact us with your platform and app version.')}</p>${link('supporto',t('Vai al supporto →','Go to support →'),'feature-link')}</div></div></div></section>`}
function baseSupport(){const qs=[
[t('21Life è un’app ufficiale di Magic?','Is 21Life an official Magic app?'),t('No. È un progetto indipendente e contenuto fan non ufficiale, non approvato, sponsorizzato o affiliato a Wizards of the Coast.','No. It is an independent, unofficial fan project and is not approved, sponsored by or affiliated with Wizards of the Coast.')],
[t('Ogni giocatore deve avere un account?','Does every player need an account?'),t('Puoi aggiungere ospiti al tavolo senza account. Per accedere al playgroup e ai propri dati condivisi serve un account.','Guests can join a table without an account. An account is required to access the playgroup and personal shared data.')],
[t('Posso usare lo stesso account su web e Android?','Can I use the same account on web and Android?'),t('Sì. Accedi con lo stesso account per ritrovare gruppo, mazzi e partite. I dati si sincronizzano quando sei online.','Yes. Sign in with the same account to access your group, decks and games. Data syncs while you are online.')],
[t('L’app funziona senza internet?','Does it work without internet?'),t('Non completamente. Puoi recuperare una partita interrotta, ma per account, sincronizzazione e importazione dei mazzi serve internet.','Not fully. You can recover an interrupted game, but accounts, syncing and deck imports need an internet connection.')],
[t('Come aggiorno l’app Android?','How do I update the Android app?'),t('Usa Obtainium con l’indirizzo GitHub di 21Life, oppure scarica l’APK dalle release ufficiali. Mantieni la stessa variante per gli aggiornamenti.','Use Obtainium with the 21Life GitHub address, or download the APK from official releases. Keep the same edition when updating.')],
[t('È disponibile su iPhone o iPad?','Is it available on iPhone or iPad?'),t('Su iPhone e iPad puoi usare la web app dal browser. 21Life non è disponibile sull’App Store.','On iPhone and iPad, use the web app in your browser. 21Life is not available on the App Store.')],
[t('Come elimino l’account e i dati?','How do I delete my account and data?'),t('Puoi eliminare definitivamente il tuo account dalle Impostazioni dell’app. Consulta la sezione qui sotto o contatta il supporto se non riesci ad accedere. Non inviare password o token quando contatti il supporto.','Permanently delete your account in the app Settings. See the section below or contact support if you cannot sign in. Never send passwords or tokens when contacting support.')]
];return heading(t('SUPPORTO / FAQ','SUPPORT / FAQ'),t('Serve una mano?','Need help?'),t('Qui trovi le risposte su installazione, account e partite. Se il problema resta, scrivi a support@21life.win.','Find answers about installation, accounts and games. If you still need help, email support@21life.win.'))+`<section class="content-section"><div class="two"><article class="card"><span class="number">01 / ${t('CONTATTO','CONTACT')}</span><h3>${t('Scrivi al supporto','Contact support')}</h3><p>${t('Indica dispositivo, versione dell’app, passaggi e messaggio di errore. Aiutaci a riprodurre il problema senza condividere dati sensibili.','Include your device, app version, steps and error message. Help us reproduce the issue without sharing sensitive data.')}</p><a class="feature-link" href="mailto:support@21life.win">support@21life.win ↗</a></article><article class="card"><span class="number">02 / ${t('COMMUNITY','COMMUNITY')}</span><h3>${t('Bug e suggerimenti','Bugs and suggestions')}</h3><p>${t('Bug e proposte si raccolgono nelle issue GitHub. Le segnalazioni sono pubbliche: rimuovi dati personali dagli screenshot.','Bugs and suggestions are collected in GitHub issues. Reports are public: remove personal data from screenshots.')}</p><a class="feature-link" href="${REPO}/issues">${t('Apri le issue →','Open the issues →')}</a></article></div></section><section class="section-panel"><div class="eyebrow">${t('DOMANDE FREQUENTI','FREQUENTLY ASKED QUESTIONS')}</div><h2>${t('Domande frequenti','Frequently asked questions')}</h2><div class="faq">${qs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section><section id="account"><div class="eyebrow">${t('PRIVACY & CONDIZIONI','PRIVACY & TERMS')}</div><h2>${t('Privacy e account','Privacy and your account')}</h2><p>${t('Questo sito usa Cloudflare Web Analytics per misurare le visite e le pagine consultate, senza cookie di analytics. Le statistiche sono riservate al gestore del sito. Per account e dati dell’app consulta l’informativa privacy.','This site uses Cloudflare Web Analytics to measure visits and page views without analytics cookies. Statistics are only accessible to the site owner. For app accounts and data, read the privacy policy.')}</p><h3>${t('Eliminazione account','Account deletion')}</h3><p>${t('Apri le Impostazioni dell’app per eliminare definitivamente il tuo account. Se non riesci ad accedere, scrivi a support@21life.win. Per conoscere conservazione e gestione dei dati consulta l’informativa privacy.','Open the app Settings to permanently delete your account. If you cannot sign in, contact support@21life.win. See the privacy policy for data retention and handling.')}</p><div class="legal-links"><a href="${APP}/legal/privacy">${t('Informativa privacy','Privacy policy')}</a><a href="${APP}/legal/terms">${t('Condizioni di servizio','Terms of service')}</a><a href="${url('supporto')}#account">${t('Eliminazione account','Account deletion')}</a><a href="${REPO}/blob/main/THIRD_PARTY_NOTICES.md">${t('Licenze e riconoscimenti','Third-party notices')}</a></div></section>`}
function draftFaqItems(){return [
 [t('21Life è gratis e open source?','Is 21Life free and open source?'),t('Sì. Il codice è pubblico con licenza MIT. Contavita, storico, statistiche, playgroup, stagioni e premi sono gratuiti, senza funzioni riservate a un piano a pagamento.','Yes. The code is public under the MIT license. The life counter, game history, statistics, playgroups, seasons and awards are free, with no paid feature tier.')],
 [t('Come importo i miei mazzi da Moxfield o Archidekt?','How do I import decks from Moxfield or Archidekt?'),t('Nel profilo apri la sezione mazzi, scegli l’importazione e incolla il link del mazzo. Controlla il risultato e salva. Serve una connessione internet; la lista originale non viene modificata.','Open the deck section in your profile, choose import and paste the deck link. Review the result and save it. Imports need an internet connection and do not change your original list.')],
 [t('21Life è l’app ufficiale di Moxfield?','Is 21Life an official Moxfield app?'),t('No. È un progetto indipendente per Commander / EDH che permette di importare mazzi da Moxfield e Archidekt. Non è affiliato a questi servizi né a Wizards of the Coast.','No. It is an independent Commander / EDH project that imports decks from Moxfield and Archidekt. It is not affiliated with either service or Wizards of the Coast.')],
 [t('È già disponibile su F-Droid?','Is 21Life available on F-Droid?'),t('Prossimamente. La proposta è in revisione. Nel frattempo puoi scaricare l’APK ufficiale da GitHub, seguirne gli aggiornamenti con Obtainium o usare la web app.','Coming soon. The submission is under review. For now, download the official APK from GitHub, follow updates with Obtainium or use the web app.')],
 [t('Tutti i giocatori devono creare un account?','Does every player need an account?'),t('No. Serve un account per gestire il playgroup e salvare storico e statistiche condivisi. Gli altri giocatori possono partecipare come ospiti, senza un proprio account.','No. You need an account to manage the playgroup and save shared history and statistics. Other players can join as guests without their own accounts.')],
 [t('Ci sono pubblicità o funzioni a pagamento?','Are there ads or paid features?'),t('No. Anche statistiche, stagioni e premi del gruppo sono inclusi. Puoi consultare, modificare e ridistribuire il codice nei termini della licenza MIT.','No. Group statistics, seasons and awards are included too. You can inspect, modify and redistribute the code under the MIT license terms.')],
 [t('Quali dati vengono trattati?','What data is processed?'),t('Account e partite condivise richiedono dati per funzionare e sincronizzarsi. Importazioni e immagini usano servizi esterni. Il sito di presentazione misura le visite con Cloudflare Web Analytics, senza cookie di analytics. Trovi i dettagli nell’informativa.','Accounts and shared games need data to work and sync. Imports and images use external services. The presentation website measures visits with Cloudflare Web Analytics, without analytics cookies. Read the policy for details.')]
];}
function draftFaq(){return `<section class="preview-faq" id="faq"><div class="eyebrow">FAQ</div><h2>${t('Prima di iniziare','Before you start')}</h2><div class="faq">${draftFaqItems().map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section>`;}
function draftOpenSource(){return `<section class="open-source-section"><div class="open-source-copy"><div class="eyebrow">FREE & OPEN SOURCE</div><h2>${t('Gratis.<br>Con il codice incluso.','Free.<br>With the source included.')}</h2><p>${t('Tutte le funzioni sono disponibili senza abbonamento. Il codice è su GitHub con licenza MIT: puoi leggerlo, modificarlo e ridistribuirlo nei termini della licenza.','All features are available without a subscription. The code is on GitHub under the MIT license: you can read, modify and redistribute it under its terms.')}</p><div class="actions">${button(REPO,t('Il codice su GitHub','Source on GitHub'))}${link('confronto',t('Confronta le alternative →','Compare alternatives →'),'text-link')}</div></div><div class="license-panel"><span>21LIFE / LICENSE</span><strong>MIT</strong><p>${t('Contavita · Statistiche · Playgroup<br>Stagioni · Premi','Life counter · Statistics · Playgroups<br>Seasons · Awards')}</p><div class="license-note">${t('Nessuna funzione a pagamento.','No paid feature tier.')}</div></div></section>`;}
function draftDownload(){return heading('DOWNLOAD',t('Scarica 21Life.','Get 21Life.'),t('Gratis e open source, con licenza MIT. Senza pubblicità o funzioni a pagamento.','Free and open source under the MIT license. No ads or paid feature tier.'))+`<section class="content-section"><div class="download-grid">
 <article class="card channel-card fdroid-card"><div class="channel-heading"><span class="channel-mark" aria-hidden="true">F</span><span class="tag">FOSS / ANDROID</span></div><h2>F-Droid</h2><p>${t('La versione FOSS per Android è in revisione. Il collegamento allo store sarà disponibile qui al lancio.','The FOSS edition for Android is under review. The store link will be available here at launch.')}</p><div class="channel-action"><span class="coming-soon">${t('Prossimamente su F-Droid','Coming soon to F-Droid')}</span></div><p class="channel-foot">${t('Nel frattempo, puoi usare GitHub o la web app.','For now, use GitHub or the web app.')}</p></article>
 <article class="card channel-card"><div class="channel-heading">${featureIcon('android')}<span class="tag">ANDROID / ${RELEASE_CONFIG.version}</span></div><h2>GitHub & Obtainium</h2><p>${t('Scarica l’APK ufficiale da GitHub. Per gli aggiornamenti, aggiungi il repository a Obtainium.','Download the official APK from GitHub. For updates, add the repository to Obtainium.')}</p><div class="channel-action">${button(APK,t('Scarica APK','Download APK'),true)}</div><a class="text-link" href="#obtainium">${t('Configura Obtainium ↓','Set up Obtainium ↓')}</a></article>
 <article class="card channel-card"><div class="channel-heading">${featureIcon('web')}<span class="tag">WEB / PWA</span></div><h2>Web app</h2><p>${t('Apri 21Life dal browser, su computer o telefono. Dove supportato, puoi aggiungerlo alla schermata Home.','Open 21Life in your browser, on a computer or phone. Add it to your home screen where supported.')}</p><div class="channel-action">${button(APP,t('Apri la web app','Open the web app'))}</div><p class="channel-foot">${t('Lo stesso account e gli stessi dati della versione Android.','The same account and data as the Android app.')}</p></article>
 </div></section><section class="section-panel" id="obtainium"><div class="two"><div><div class="eyebrow">OBTAINIUM</div><h2>${t('Gli aggiornamenti,<br>direttamente da GitHub.','Updates,<br>straight from GitHub.')}</h2><p>${t('Obtainium controlla le release di 21Life e ti avvisa quando esce una nuova versione.','Obtainium checks 21Life releases and lets you know when a new version is available.')}</p>${button('https://obtainium.imranr.dev/',t('Scarica Obtainium','Get Obtainium'))}</div><div><ol class="steps"><li><h3>${t('Installa Obtainium','Install Obtainium')}</h3><p>${t('Scaricalo dal sito ufficiale.','Download it from its official website.')}</p></li><li><h3>${t('Aggiungi 21Life','Add 21Life')}</h3><p>${t('In “Aggiungi app”, incolla questo indirizzo.','In “Add App”, paste this address.')}</p><div class="copy-row"><code>${REPO}</code><button data-copy type="button">${t('Copia','Copy')}</button></div><span id="copy-status" role="status"></span></li><li><h3>${t('Conferma la release','Confirm the release')}</h3><p>${t('Controlla l’app rilevata e procedi con l’installazione.','Check the detected app and continue with installation.')}</p></li></ol></div></div></section><section><p class="note">${t('Usa i canali ufficiali e verifica i checksum pubblicati. Per gli aggiornamenti mantieni lo stesso canale: le versioni GitHub e F-Droid possono avere firme e servizi diversi.','Use official channels and verify published checksums. Keep the same channel for updates: GitHub and F-Droid versions may use different signatures and services.')}</p></section>`;}
function draftImportGuide(){return `<section class="deck-import-panel" id="importa-mazzi"><div class="deck-import-grid"><div class="deck-import-copy"><div><div class="eyebrow">MOXFIELD / ARCHIDEKT</div><h2>${t('Hai già la lista.<br>Importa il mazzo.','Already have a list?<br>Import your deck.')}</h2><p>${t('Non devi ricreare i mazzi che hai già su Moxfield o Archidekt. L’importazione li aggiunge al tuo profilo 21Life, dove puoi associarli alle partite.','You do not need to recreate decks you already have on Moxfield or Archidekt. Import them into your 21Life profile and use them in your games.')}</p></div></div><div><ol class="steps"><li><h3>${t('Copia il link del mazzo','Copy the deck link')}</h3><p>${t('Apri la lista sul servizio di origine e copia il suo indirizzo.','Open the list on the source service and copy its URL.')}</p></li><li><h3>${t('Apri la sezione mazzi','Open your decks')}</h3><p>${t('Dal profilo 21Life scegli l’importazione e incolla il link.','In your 21Life profile, choose import and paste the link.')}</p></li><li><h3>${t('Controlla e salva','Review and save')}</h3><p>${t('Verifica il mazzo importato prima di usarlo in partita. La lista originale non cambia; servono internet e accesso alla lista.','Review the imported deck before using it in a game. Your original list stays unchanged; internet and access to the list are required.')}</p></li></ol></div></div></section>`;}
function draftComparison(){const rows=[
 [t('Costo','Cost'),t('Gratis. Nessuna funzione a pagamento.','Free. No paid feature tier.'),t('Tracking e statistiche dichiarati gratuiti.','Tracking and statistics described as free.'),t('Dichiarato gratuito, senza pubblicità.','Described as free, without ads.')],
 [t('Codice open source','Open source code'),t('Pubblico, licenza MIT.','Public, MIT license.'),t('Licenza open source non identificata nelle fonti consultate.','Open source license not identified in the reviewed sources.'),t('Licenza open source non identificata nelle fonti consultate.','Open source license not identified in the reviewed sources.')],
 [t('Storico e statistiche','History and statistics'),t('Storico condiviso, risultati di giocatori e mazzi.','Shared history, player and deck results.'),t('Tracking condiviso, ELO e statistiche dei mazzi.','Shared tracking, ELO and deck statistics.'),t('Storico salvato e statistiche di giocatori e mazzi.','Saved history and player and deck statistics.')],
 ['Moxfield / Archidekt',t('Importazione dei mazzi.','Deck imports.'),t('Importazioni documentate per Playgroup Live, il tavolo virtuale separato.','Imports documented for Playgroup Live, its separate virtual tabletop.'),t('Importazioni non documentate nelle fonti consultate.','Imports not documented in the reviewed sources.')],
 [t('Gruppi','Groups'),t('Playgroup privati, ospiti, stagioni e premi inclusi.','Private playgroups, guests, seasons and awards included.'),t('Playgroup, ospiti, classifiche e leghe Playscore.','Playgroups, guests, leaderboards and Playscore leagues.'),t('Profili giocatore salvati; stagioni condivise non documentate.','Saved player profiles; shared seasons not documented.')],
 [t('Account','Accounts'),t('Per gestire gruppi e statistiche condivise. Ospiti senza account.','For group management and shared statistics. Guests need no account.'),t('Almeno un account per ospitare e salvare le partite. Ospiti supportati.','At least one account to host and save games. Guests supported.'),t('Uso base senza account, dati locali; funzioni cloud opzionali descritte nella privacy.','Basic use without an account, local data; optional cloud features described in its policy.')],
 ['F-Droid',t('Prossimamente.','Coming soon.'),t('Disponibilità non accertata nelle fonti consultate.','Availability not established in the reviewed sources.'),t('Disponibilità non accertata nelle fonti consultate.','Availability not established in the reviewed sources.')]
 ];return heading(t('CONFRONTO','COMPARISON'),'21Life, Playgroup<br>'+t('o Lifetap?','or Lifetap?'),t('Tre opzioni per Commander. Qui trovi cosa offrono e perché potresti scegliere un progetto open source.','Three options for Commander. Here is what they offer and why you might choose an open source project.'))+`<section class="comparison-intro"><p class="lead">${t('21Life è gratuito e pubblica il codice con licenza MIT. Contavita, storico, statistiche, gruppi, stagioni e premi sono inclusi. Anche Playgroup e Lifetap offrono strumenti gratuiti: l’accesso al codice è uno dei motivi per considerare 21Life.','21Life is free and publishes its code under the MIT license. Its life counter, history, statistics, groups, seasons and awards are included. Playgroup and Lifetap also offer free tools: access to the code is one reason to consider 21Life.')}</p><p class="comparison-disclosure">${t('Confronto a cura del progetto 21Life · Fonti consultate il 19 ottobre 2026.','Comparison by the 21Life project · Sources reviewed on 19 October 2026.')}</p></section><section class="comparison-section"><div class="table-scroll" tabindex="0" role="region" aria-label="${t('Tabella confronto applicazioni, scorrimento orizzontale','Application comparison table, scroll horizontally')}"><table><caption>${t('Funzioni, gratuità e licenza','Features, cost and license')}</caption><thead><tr><th scope="col">${t('Aspetto','Aspect')}</th><th scope="col">21Life</th><th scope="col">Playgroup.gg</th><th scope="col">Lifetap</th></tr></thead><tbody>${rows.map(([name,...values])=>`<tr><th scope="row">${name}</th>${values.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="table-note">${t('“Non documentato” significa che le fonti consultate non confermano quella funzione o licenza, non che sia assente. Su telefono puoi scorrere la tabella in orizzontale.','“Not documented” means the reviewed sources do not confirm the feature or license, not that it is absent. On a phone, scroll the table horizontally.')}</p></section><section class="two comparison-reasons"><article><div class="eyebrow">MIT LICENSE</div><h2>${t('Gratis da usare.<br>Libero da modificare.','Free to use.<br>Free to modify.')}</h2><p>${t('Un’app può essere gratuita senza rendere pubblico il codice. 21Life offre entrambe le cose: usi le funzioni senza abbonamento e puoi leggere, modificare e ridistribuire il software nei termini della licenza MIT.','An app can be free without publishing its code. 21Life offers both: use the features without a subscription, and read, modify and redistribute the software under the MIT license.')}</p>${button(REPO,t('Leggi il codice e la licenza','Read the code and license'))}</article><article><div class="eyebrow">${t('LA SCELTA DEL TUO GRUPPO','YOUR GROUP’S CHOICE')}</div><h2>${t('Conta quello<br>che vi serve.','Choose what<br>your group needs.')}</h2><p>${t('Playgroup documenta statistiche ELO e un tavolo virtuale separato. Lifetap offre uso locale senza account e più modalità da tavolo. Sono esigenze diverse dall’accesso al codice: scegli in base a come giocate.','Playgroup documents ELO statistics and a separate virtual tabletop. Lifetap offers local use without an account and several tabletop modes. Those needs differ from access to source code: choose based on how you play.')}</p></article></section><section class="section-panel"><h2>${t('Open source e privacy','Open source and privacy')}</h2><p>${t('Il codice aperto può essere esaminato. Non significa che non vengano trattati dati: account e partite condivise richiedono archiviazione e sincronizzazione. Anche importazioni, immagini e statistiche delle visite hanno servizi e informative da considerare.','Open code can be inspected. It does not mean no data is processed: accounts and shared games require storage and sync. Imports, images and website analytics also involve services and privacy policies.')}</p>${link('supporto',t('Privacy e domande frequenti →','Privacy and FAQ →'),'text-link')}</section><section class="source-section"><h2>${t('Fonti','Sources')}</h2><div class="source-links"><a href="${REPO}">21Life / MIT ↗</a><a href="https://playgroup.gg/">Playgroup / ${t('funzioni','features')} ↗</a><a href="https://playgroup.gg/posts/98-playgroup-live-looking-for-testers">Playgroup Live / ${t('importazioni','imports')} ↗</a><a href="https://getlifetap.com/">Lifetap / ${t('funzioni','features')} ↗</a><a href="https://getlifetap.com/privacy">Lifetap / privacy ↗</a><a href="https://playgroup.gg/privacy">Playgroup / privacy ↗</a></div><p>${t('Le informazioni dei concorrenti provengono dai rispettivi siti ufficiali. Non sono un audit indipendente.','Competitor information comes from their official sites. This is not an independent audit.')}</p></section>`;}


function info(){return baseInfo()+draftOpenSource();}
function guide(){return baseGuide()+draftImportGuide();}
function support(){return baseSupport()+draftFaq();}
const draftMetadata={"/":{"title":"21Life — Open Source Commander Life Counter & EDH Tracker","description":"A free, MIT-licensed Commander life counter with game history, pod statistics and Moxfield or Archidekt deck imports. Available on Android and web.","h1":"Commander life counter. Open source. Free."},"/info/":{"title":"Free MTG Pod Analytics & Deck Statistics — 21Life","description":"Track your Commander playgroup, compare deck results and run seasons with awards. Free, open source under the MIT license, with no feature paywalls.","h1":"Your pod, decks and results."},"/download/":{"title":"Download 21Life — Android APK, Obtainium & Web App","description":"Get 21Life from GitHub, keep it updated with Obtainium or use the web app. Free and open source. F-Droid availability is coming soon.","h1":"Get 21Life."},"/guida/":{"title":"Import Moxfield & Archidekt Decks into 21Life — Guide","description":"Add your Moxfield or Archidekt decks to 21Life, set up your Commander playgroup and start recording games. A short guide for Android and web.","h1":"Your first game with 21Life."},"/supporto/":{"title":"21Life FAQ — Open Source, Accounts & F-Droid","description":"Answers about 21Life: MIT license, free features, deck imports, guest players, account requirements, privacy and the upcoming F-Droid release.","h1":"Questions about 21Life?"},"/confronto/":{"title":"21Life vs Playgroup and Lifetap — Open Source EDH Tracker","description":"Compare Commander trackers by license, cost, deck imports and playgroup features. See where 21Life fits alongside Playgroup and Lifetap.","h1":"21Life, Playgroup or Lifetap?"}};
function draftSyncMetadata(){
 const pathname=route==='home'?'/':'/'+route+'/';
 const meta=draftMetadata[pathname];
 const titles={home:'21Life — Tracker Commander gratuito e open source',info:'Statistiche e playgroup — 21Life',download:'Scarica 21Life — APK, Obtainium e Web',guida:'Importa mazzi Moxfield e Archidekt — 21Life',confronto:'21Life, Playgroup o Lifetap — Confronto',supporto:'FAQ, account e privacy — 21Life'};
 const descriptions={home:'Contavita Commander, storico e statistiche dei mazzi. 21Life è gratuito e open source con licenza MIT, per Android e web.',info:'Statistiche di mazzi e giocatori, playgroup, stagioni e premi senza funzioni a pagamento. Codice disponibile con licenza MIT.',download:'Scarica l’APK ufficiale, usa Obtainium per gli aggiornamenti o apri la web app. Prossimamente su F-Droid.',guida:'Importa i mazzi da Moxfield e Archidekt, crea il tuo playgroup e registra la prima partita Commander.',confronto:'Confronta 21Life, Playgroup e Lifetap per gratuità, licenza, funzioni e gestione del gruppo.',supporto:'Risposte su gratuità, licenza MIT, importazioni, account, privacy e F-Droid.'};
 document.title=lang==='it'?titles[route]:meta.title;
 if(typeof document.head==='undefined')return;
 const description=lang==='it'?descriptions[route]:meta.description;
 document.querySelector('meta[name="description"]')?.setAttribute('content',description);
 document.querySelector('meta[property="og:title"]')?.setAttribute('content',document.title);
 document.querySelector('meta[property="og:description"]')?.setAttribute('content',description);
 document.querySelector('meta[property="og:locale"]')?.setAttribute('content',lang==='it'?'it_IT':'en_US');
 const schema=document.querySelector('#draft-faq-schema');
 if(schema)schema.textContent=JSON.stringify({'@context':'https://schema.org','@type':'FAQPage',inLanguage:lang,mainEntity:draftFaqItems().map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))});
}
function render(){renderBase();draftSyncMetadata();}

function renderBase(){const labels=navLabels();document.documentElement.lang=lang;document.title=({home:t('21Life — Contavita Commander e statistiche','21Life — Commander Life Counter & EDH Game Tracker'),info:t('Funzioni — 21Life','Commander Tracker Features — 21Life'),download:t('Scarica 21Life — Android e Web','Download 21Life — Android & Web Commander Tracker'),guida:t('Come iniziare — 21Life','Getting Started with 21Life — Commander Tracker Guide'),supporto:t('Supporto e FAQ — 21Life','21Life Support & FAQ — Accounts, Downloads and Privacy')})[route];document.querySelector('#site').innerHTML=`<a class="skip" href="#main">${t('Salta al contenuto','Skip to content')}</a><header><div class="wrap nav"><a class="brand" href="${url('home')}" aria-label="21Life Home"><img class="brand-emblem" src="/assets/emblem.png" alt="" width="42" height="42"><img class="brand-wordmark" src="/assets/wordmark.png" alt="21Life" width="128" height="50"></a><nav class="navlinks" id="navigation" aria-label="${t('Navigazione principale','Main navigation')}">${routes.map((r,i)=>link(r,labels[i])).join('')}</nav><button class="lang" type="button" data-lang aria-label="${t('Switch to English','Passa a italiano')}">${lang==='it'?'EN':'IT'}</button><a class="btn primary small" href="${APP}">${t('Apri app','Open app')} ↗</a><button class="menu" type="button" data-menu aria-controls="navigation" aria-expanded="false" aria-label="Menu">☰</button></div></header><main id="main" class="wrap">${({home,info,download,guida:guide,confronto:draftComparison,supporto:support})[route]()}</main><footer><div class="wrap"><div class="footer-top"><div><a class="brand" href="${url('home')}" aria-label="21Life Home"><img class="brand-emblem" src="/assets/emblem.png" alt="" width="42" height="42"><img class="brand-wordmark" src="/assets/wordmark.png" alt="21Life" width="128" height="50"></a><p>Tracker & Analytics<br>${t('Tracker Commander gratuito e open source.','Free, open source Commander tracker.')}</p></div><div class="footer-nav"><div><strong>21Life</strong>${link('info',labels[1])}${link('download',labels[2])}${link('guida',labels[3])}${link('confronto',labels[4])}</div><div><strong>${t('Risorse','Resources')}</strong>${link('supporto',labels[5])}<a href="${REPO}">GitHub ↗</a><a href="https://www.instagram.com/21life.win/" rel="me noopener noreferrer">Instagram ↗</a><a href="mailto:support@21life.win">${t('Contattaci','Contact us')}</a></div><div><strong>${t('Legale','Legal')}</strong><a href="${APP}/legal/privacy">Privacy</a><a href="${APP}/legal/terms">${t('Condizioni','Terms')}</a><a href="${url('supporto')}#account">${t('Elimina account','Delete account')}</a></div></div></div><div class="footer-bottom"><p>© ${new Date().getFullYear()} 21Life · ${t('Contenuto fan non ufficiale. Non approvato né sponsorizzato da Wizards of the Coast. Magic: The Gathering e i relativi marchi appartengono ai rispettivi titolari.','Unofficial fan content. Not approved or sponsored by Wizards of the Coast. Magic: The Gathering and related trademarks belong to their respective owners.')}</p><div class="status">Open source · MIT</div></div></div></footer>`;}
render();
document.addEventListener('click',async(event)=>{const target=event.target.closest('button');if(!target)return;if(target.hasAttribute('data-lang')){lang=lang==='it'?'en':'it';history.replaceState(null,'',url(route));render();document.querySelector('[data-lang]').focus()}if(target.hasAttribute('data-menu')){const open=document.querySelector('#navigation').classList.toggle('open');target.setAttribute('aria-expanded',String(open))}if(target.hasAttribute('data-copy')){try{await navigator.clipboard.writeText(REPO);document.querySelector('#copy-status').textContent=t('Indirizzo copiato.','Address copied.')}catch{document.querySelector('#copy-status').textContent=t('Seleziona e copia l’indirizzo mostrato sopra.','Select and copy the address above.')}}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelector('#navigation').classList.remove('open');document.querySelector('[data-menu]').setAttribute('aria-expanded','false')}});
